export default function next({ data, cursor, previous, owner, repo, basePath }) {
  if (!owner || !repo || owner.includes("YOUR_") || repo.includes("YOUR_"))
    throw Error("Configure repository");
  const parts = basePath.split("/").filter(Boolean);
  if (parts.some((x) => x === "." || x === ".." || !/^[-\w.]+$/.test(x)))
    throw Error("Invalid backup path");
  let s = previous ?? { queue: [], index: 0, cursor: null, phase: "list" };
  if (s.phase === "await-list") {
    if (!Array.isArray(data)) throw Error("Invalid workflow page");
    s.queue = data.map((w) => ({ id: w.id, tags: (w.tags ?? []).slice(0, 1) }));
    s.index = 0;
    s.nextCursor = cursor ?? null;
    s.phase = "items";
  }
  for (;;) {
    if (s.phase === "list") {
      s.phase = "await-list";
      return { state: s, step: "list", cursor: s.cursor, id: "-", path: "-", endpoint: "/unused" };
    }
    if (s.phase === "items" && s.index < s.queue.length) {
      const w = s.queue[s.index++];
      if (!/^[\w-]+$/.test(String(w.id ?? ""))) throw Error("Invalid workflow ID");
      const tag = w.tags?.[0]?.name;
      if (tag != null && (tag === "." || tag === ".." || !/^[-\w.]+$/.test(tag)))
        throw Error("Unsafe tag name");
      const path = [...parts, ...(tag ? [tag] : []), String(w.id) + ".json"].join("/");
      return {
        state: s,
        step: "item",
        cursor: null,
        id: String(w.id),
        path,
        endpoint:
          "/repos/" +
          encodeURIComponent(owner) +
          "/" +
          encodeURIComponent(repo) +
          "/contents/" +
          path.split("/").map(encodeURIComponent).join("/"),
      };
    }
    if (s.nextCursor) {
      s.cursor = s.nextCursor;
      s.nextCursor = null;
      s.phase = "list";
      continue;
    }
    return { state: s, step: "done", cursor: null, id: "-", path: "-", endpoint: "/unused" };
  }
}

