import { Buffer } from "node:buffer";
export default async function plan(
  { workflow, id, path, owner, repo, status, body, acknowledge, resolution },
  ctx,
) {
  if (String(workflow?.id) !== id) throw Error("Workflow ID mismatch");
  if (![200, 404].includes(status)) throw Error("GitHub read failed " + status);
  const key = "n8n-github:" + owner + "/" + repo + "/" + path;
  const sort = (x) =>
    JSON.stringify(Object.fromEntries(Object.entries(x).sort(([a], [b]) => a.localeCompare(b))));
  const desired = sort(workflow);
  let sha = null,
    same = false;
  if (status === 200) {
    if (
      body?.type !== "file" ||
      body.path !== path ||
      !body.sha ||
      body.encoding !== "base64" ||
      !body.content
    )
      throw Error("Unsupported or invalid existing GitHub file");
    sha = body.sha;
    let old;
    try {
      old = JSON.parse(Buffer.from(body.content.replace(/\s/g, ""), "base64").toString("utf8"));
    } catch {
      throw Error("Existing backup is not JSON");
    }
    same = sort(old) === desired;
  }
  const pending = await ctx.state.get(key);
  if (pending) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + key);
    if (resolution === "confirmed") {
      if (!same) throw Error("Destination does not match intended workflow");
      await ctx.state.set(key, null);
      return { write: false, key, sha: null, content: desired, message: "Backup " + id };
    }
    if (status !== pending.status || sha !== pending.sha)
      throw Error("Destination changed; reconcile first");
    await ctx.state.set(key, null);
  }
  if (same) return { write: false, key, sha: null, content: desired, message: "Backup " + id };
  await ctx.state.set(key, { status, sha });
  return { write: true, key, sha, content: desired, message: "Back up workflow " + id };
}

